+            Files.createFile(jar);
+            policyString.append(" codeBase \"" + jar.toUri().toURL().toString() + "\"");
+        }
+        policyString.append(" {\n  permission ");
+        policyString.append(clazz);
+        // wildcard
+        policyString.append(" \"" + name + "\"");
